"use client";
import React,{useState} from "react";
import api from "@/lib/api";
import {useResource,Table,Badge,Notice,date,bytes,remaining,message,panel} from "./BillingUI";
interface User {id:number;customerId:number|null;customerName:string|null;phone:string|null;voucher:string;packageName:string;status:string;online:boolean;ip:string|null;mac:string|null;router:string|null;deviceLimit:number;devices:number;firstLogin:string|null;expiresAt:string|null;dataBytes:number;timeLeftSeconds:number|null}
export default function UserDirectory({expired=false}:{expired?:boolean}){
 const {data,loading,error,load}=useResource<User>("/api/users",true);const [tab,setTab]=useState("ONLINE");const [note,setNote]=useState("");
 const active=data.filter(u=>u.status==="active");const online=active.filter(u=>u.online);const offline=active.filter(u=>!u.online);
 const rows=expired?data.filter(u=>["expired","revoked"].includes(u.status)):tab==="ONLINE"?online:tab==="OFFLINE"?offline:active;
 const action=async(u:User)=>{if(!confirm(expired?"Archive this expired record? Payment and accounting history will be retained.":`Send a disconnect request for ${u.voucher}?`))return;try{await api.post(expired?`/api/vouchers/${u.voucher}/archive`:"/api/sessions/disconnect",expired?{}:{username:u.voucher});setNote(expired?"Record archived.":"Disconnect request sent. Check accounting for confirmation.");await load();}catch(e){setNote(message(e));}};
 return <div className="mx-auto max-w-7xl space-y-6"><h1 className="text-2xl font-semibold text-slate-900">{expired?"Expired users":"Active users"}</h1>{!expired&&<><div className="grid gap-4 sm:grid-cols-3">{[["All active",active.length,"Vouchers within their validity period"],["Online now",online.length,"Fresh accounting received in the last 6 minutes"],["Offline",offline.length,"Active access with no recent session"]].map(([label,value,hint])=><div key={label} className={`${panel} p-5`}><p className="text-xs text-slate-500">{label}</p><p className="mt-3 text-2xl font-semibold text-slate-900">{value}</p><p className="mt-2 text-xs text-slate-500">{hint}</p></div>)}</div><div className="flex gap-2">{["ONLINE","OFFLINE","ALL"].map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg border px-4 py-2 text-xs ${t===tab?"border-blue-200 bg-blue-50 text-blue-700":"border-slate-300 text-slate-500"}`}>{t==="ALL"?"All active":t==="ONLINE"?"Online now":"Offline"}</button>)}</div></>}
 <Notice text={error||note}/><Table rows={rows} loading={loading} columns={[
 {label:"Customer",render:u=>u.customerName|| (u.customerId?`C${u.customerId}`:"Unassigned")},{label:"Phone",render:u=>u.phone||"—"},{label:"Voucher",render:u=><Badge tone="amber">{u.voucher}</Badge>},{label:"Package",render:u=>u.packageName},{label:"IP",render:u=>u.ip||"—"},{label:"MAC",render:u=>u.mac||"—"},{label:"Devices",render:u=>`${u.devices}/${u.deviceLimit}`},{label:"Data policy",render:()=>"Unlimited"},{label:"Router",render:u=>u.router||"—"},{label:"First login",render:u=>date(u.firstLogin)},{label:"Expires",render:u=>date(u.expiresAt)},{label:"Data usage",render:u=>bytes(u.dataBytes)},{label:"Time left",render:u=><Badge tone={expired?"red":"green"}>{remaining(u.timeLeftSeconds)}</Badge>},{label:"Action",render:u=><button disabled={!expired&&!u.online} onClick={()=>action(u)} className="text-red-600 disabled:opacity-30">{expired?"Archive":"Disconnect"}</button>}
 ]}/></div>;
}
